let t_score = 'ND';
let t_protestos = 'ND';
let t_execucoes = 'ND';
let t_spc = 'ND';
let gate_disparado = null;

try {
  const resp = $json;
  const report = Array.isArray(resp) ? resp[0] : resp;
  const rel = report?.reports?.[0] ?? null;

  if (rel) {
    // ---- Score (numero bruto -- pontosBanda faz a classificacao por faixa) ----
    const scoreVal = report?.optionalFeatures?.score?.score;
    if (typeof scoreVal === 'number') t_score = scoreVal;

    // ---- Protestos: negativeData.notary.summary.count ----
    const protestosCount = rel?.negativeData?.notary?.summary?.count;
    if (typeof protestosCount === 'number') t_protestos = protestosCount;

    // ---- Execucoes relevantes: facts.judgementFilings.summary.count ----
    const execucoesCount = rel?.facts?.judgementFilings?.summary?.count;
    if (typeof execucoesCount === 'number') t_execucoes = execucoesCount;

    // ---- "SPC" (proxy: pefin -- Pendencias Financeiras da propria Serasa, nao e literalmente SPC) ----
    const pefinCount = rel?.negativeData?.pefin?.summary?.count;
    if (typeof pefinCount === 'number') {
      t_spc = pefinCount > 0 ? 'Sim' : 'Não';
    }

    // ---- Gate G2: falencia / recuperacao judicial ----
    // ---- Gate G2: falencia / recuperacao judicial (2 fontes combinadas) ----
    const bankruptsCount = rel?.facts?.bankrupts?.summary?.count;
    const emRJDireto = $('When Executed by Another Workflow').item.json.em_recuperacao_judicial === true;

    if (emRJDireto) {
      gate_disparado = 'G2: recuperação judicial (Direct Data)';
    } else if (typeof bankruptsCount === 'number' && bankruptsCount > 0) {
      gate_disparado = 'G2: recuperação judicial ou falência (Serasa)';
    }
  }
} catch (e) {
  // Qualquer formato inesperado -> tudo ND, nunca trava o fluxo.
}

return [{ json: { t_score, t_protestos, t_execucoes, t_spc, gate_disparado } }];
